        statuses = (statuses == null || statuses.isEmpty())
                ? Set.of()
                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
    }

    /** A filter on the name only. */
    public static CustomerFilter byName(String name) {
        return new CustomerFilter(name, Set.of());
    }

    /** A filter on the status only. */
    public static CustomerFilter byStatus(CustomerStatus... statuses) {
        return new CustomerFilter("", Set.of(statuses));
    }

