/**
 * The criteria a customer must satisfy to be listed.
 *
 * <p>This is what the UI hands to the backend; {@link CustomerRepository}
 * applies it to both the page query and the count query, so the grid stays
 * lazily loaded no matter how narrow the filter is.
 *
 * <p>A customer matches when it satisfies <em>both</em> parts:
 * <ul>
 * <li>{@code name}: every whitespace-separated term must occur in the first or
 * the last name, ignoring case and accents. An empty name matches everyone.</li>
 * <li>{@code statuses}: the customer's status must be one of the selected ones.
 * An empty selection matches every status.</li>
 * </ul>
 *
 * @param name     the name terms, whitespace-normalised; never {@code null}
 * @param statuses the accepted statuses, in declaration order; never {@code null}
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** Matches every customer. */
    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = (name == null) ? "" : WHITESPACE.matcher(name.strip()).replaceAll(" ");
        statuses = (statuses == null || statuses.isEmpty())
                ? Set.of()
                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
    }

    /** A filter on the name only. */
    public static CustomerFilter byName(String name) {
        return new CustomerFilter(name, Set.of());
    }

    /** A filter on the status only. */
    public static CustomerFilter byStatus(CustomerStatus... statuses) {
        return new CustomerFilter("", Set.of(statuses));
    }

    /** {@code true} when this filter accepts every customer. */
    public boolean isEmpty() {
        return name.isEmpty() && statuses.isEmpty();
    }

    /** The name filter split into the terms that must all match. */
    public List<String> terms() {
        return name.isEmpty() ? List.of() : List.of(name.split(" "));
    }

    /** {@code true} when the given customer satisfies this filter. */
    public boolean matches(Customer customer) {
        return asPredicate().test(customer);
