import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;
import java.util.Set;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;

/** The backend does the filtering, the paging, the sorting and the counting. */
@SpringBootTest
class CustomerRepositoryTest {

    @Autowired
    private CustomerRepository repository;

    @Autowired
    private QueryLog queryLog;

    @BeforeEach
    void clearLog() {
        queryLog.clear();
    }

    @Test
    void countsMatchesNotRows() {
        int all = repository.count();
        int makinen = repository.count(CustomerFilter.byName("makinen"));
        assertEquals(500, all);
        assertTrue(makinen > 0 && makinen < all);
        assertEquals(List.of(500, makinen), queryLog.countQueries(),
                "each count must be recorded exactly once");
    }

    @Test
    void pagesOnlyContainMatches() {
        CustomerFilter filter = new CustomerFilter("makinen", Set.of(CustomerStatus.ACTIVE));
        List<Customer> page = repository.findAll(filter, 0, 10, List.of());

        assertTrue(page.size() <= 10);
        page.forEach(customer -> assertTrue(filter.matches(customer), "unexpected " + customer));
        assertEquals(1, queryLog.pageQueries().size(), "one page query per call");
        assertEquals(page.size(), queryLog.pageQueries().get(0).rowsReturned());
    }

    @Test
    void filteredPagingWalksTheMatchesInOrder() {
        CustomerFilter filter = CustomerFilter.byName("a");
        int matches = repository.count(filter);
        List<CustomerSort> sorts = List.of(new CustomerSort("lastName", true));

        List<Customer> first = repository.findAll(filter, 0, 100, sorts);
        List<Customer> second = repository.findAll(filter, 100, 100, sorts);
        assertEquals(100, first.size());
        assertEquals(Math.min(100, matches - 100), second.size());
        assertTrue(first.get(99).lastName().compareToIgnoreCase(second.get(0).lastName()) <= 0);
    }

    @Test
    void filteringDoesNotLiftThePageLimit() {
        assertThrows(IllegalArgumentException.class,
                () -> repository.findAll(CustomerFilter.byName("a"), 0,
                        CustomerRepository.MAX_PAGE_SIZE + 1, List.of()));
    }

    @Test
    void unfilteredCallsStillWork() {
        assertEquals(200, repository.findAll(0, 200, List.of()).size());
        assertEquals(500, repository.count());
    }
}
