+package com.example.customers.domain;
+
+import java.io.Serializable;
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.Collections;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * The criteria a customer must satisfy to be listed.
+ *
+ * <p>This is what the UI hands to the backend; {@link CustomerRepository}
+ * applies it to both the page query and the count query, so the grid stays
+ * lazily loaded no matter how narrow the filter is.
+ *
+ * <p>A customer matches when it satisfies <em>both</em> parts:
+ * <ul>
+ * <li>{@code name}: every whitespace-separated term must occur in the first or
+ * the last name, ignoring case and accents. An empty name matches everyone.</li>
+ * <li>{@code statuses}: the customer's status must be one of the selected ones.
+ * An empty selection matches every status.</li>
+ * </ul>
+ *
+ * @param name     the name terms, whitespace-normalised; never {@code null}
+ * @param statuses the accepted statuses, in declaration order; never {@code null}
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) implements Serializable {
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");
+
+    /** Matches every customer. */
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = (name == null) ? "" : WHITESPACE.matcher(name.strip()).replaceAll(" ");
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
+    }
+
+    /** A filter on the name only. */
+    public static CustomerFilter byName(String name) {
+        return new CustomerFilter(name, Set.of());
+    }
+
+    /** A filter on the status only. */
+    public static CustomerFilter byStatus(CustomerStatus... statuses) {
+        return new CustomerFilter("", Set.of(statuses));
+    }
+
+    /** {@code true} when this filter accepts every customer. */
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    /** The name filter split into the terms that must all match. */
+    public List<String> terms() {
+        return name.isEmpty() ? List.of() : List.of(name.split(" "));
+    }
+
+    /** {@code true} when the given customer satisfies this filter. */
+    public boolean matches(Customer customer) {
+        return asPredicate().test(customer);
+    }
+
+    /**
+     * Returns this filter as a predicate. The terms are normalised once, so the
+     * returned predicate is the cheap way to apply the filter to many rows.
+     */
+    public Predicate<Customer> asPredicate() {
+        if (isEmpty()) {
+            return customer -> true;
+        }
+        List<String> terms = terms().stream().map(CustomerFilter::normalize).toList();
+        Set<CustomerStatus> accepted = statuses;
+        return customer -> matchesStatus(customer, accepted) && matchesName(customer, terms);
+    }
+
+    private static boolean matchesStatus(Customer customer, Set<CustomerStatus> accepted) {
+        return accepted.isEmpty() || accepted.contains(customer.status());
+    }
+
+    private static boolean matchesName(Customer customer, List<String> normalisedTerms) {
+        if (normalisedTerms.isEmpty()) {
+            return true;
+        }
+        String firstName = normalize(customer.firstName());
+        String lastName = normalize(customer.lastName());
+        return normalisedTerms.stream()
+                .allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    /**
+     * Folds a string down to what matching compares: lower case, without
+     * accents. {@code "Mäkinen"} and {@code "MAKINEN"} both become
+     * {@code "makinen"}.
+     */
+    public static String normalize(String value) {
+        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
+        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+
+    /** The statuses in {@link CustomerStatus} declaration order. */
+    public List<CustomerStatus> statusesInDeclarationOrder() {
+        return Arrays.stream(CustomerStatus.values()).filter(statuses::contains).toList();
+    }
+}
