+        queryLog.clear();
+
+        typeName("makinen");
+        page.waitForCondition(() -> !summary().equals("Showing 500 of 500"));
+        waitForVaadin();
+
+        assertEquals("Showing 15 of 500", summary());
+        assertEquals("/?name=makinen", path());
+        assertEquals(historyBefore, (int) (Integer) page.evaluate("() => window.history.length"),
