+    }
+
+    /** Both halves of the filter, changed one after the other. */
+    @Test
+    void theAddressBarKeepsUpWithEveryChange() {
+        open("/");
+
+        typeName("makinen");
+        page.waitForCondition(() -> path().equals("/?name=makinen"));
