+        open("/?name=vir");
+        assertEquals("/?name=vir", path());
+
+        page.locator("#name-filter input").fill("");
+        page.locator("#name-filter input").blur();
+        page.waitForCondition(() -> summary().equals("Showing 500 of 500"));
+        waitForVaadin();
+
+        assertEquals("/", path());
+    }
+}
