+    void emptyFilterMatchesEveryone() {
+        assertTrue(CustomerFilter.EMPTY.isEmpty());
+        assertTrue(CustomerFilter.EMPTY.matches(ADA));
+        assertTrue(CustomerFilter.EMPTY.matches(JARNO));
+        assertTrue(CustomerFilter.EMPTY.matches(JOSEPHINE));
+    }
+
+    @Test
+    void everyTermMustMatchAName() {
+        assertTrue(CustomerFilter.byName("ada aal").matches(ADA));
+        assertTrue(CustomerFilter.byName("aal ada").matches(ADA));
+        assertFalse(CustomerFilter.byName("ada virtanen").matches(ADA));
+    }
+
+    @Test
+    void whitespaceIsNotSignificant() {
+        CustomerFilter filter = CustomerFilter.byName("   ada    aal   ");
+        assertEquals("ada aal", filter.name());
+        assertEquals(List.of("ada", "aal"), filter.terms());
+        assertTrue(filter.matches(ADA));
+        assertTrue(CustomerFilter.byName("   ").isEmpty());
+    }
+
+    @Test
+    void matchingIgnoresCaseAndAccentsBothWays() {
+        assertTrue(CustomerFilter.byName("makinen").matches(JARNO));
+        assertTrue(CustomerFilter.byName("MAKINEN").matches(JARNO));
+        assertTrue(CustomerFilter.byName("mäkinen").matches(JARNO));
+        assertTrue(CustomerFilter.byName("MÄKINEN").matches(JARNO));
+        assertTrue(CustomerFilter.byName("josephine").matches(JOSEPHINE));
+        assertTrue(CustomerFilter.byName("joséphine").matches(JOSEPHINE));
+    }
+
+    @Test
+    void nameMatchesEitherFirstOrLastName() {
+        assertTrue(CustomerFilter.byName("aalto").matches(ADA));
+        assertTrue(CustomerFilter.byName("ada").matches(ADA));
+        assertFalse(CustomerFilter.byName("example.com").matches(ADA), "only the names are searched");
+    }
+
+    @Test
+    void statusesNarrowAndDefaultToAll() {
+        assertTrue(CustomerFilter.byStatus(CustomerStatus.ACTIVE).matches(ADA));
+        assertFalse(CustomerFilter.byStatus(CustomerStatus.ACTIVE).matches(JARNO));
+        assertTrue(CustomerFilter.byStatus(CustomerStatus.ACTIVE, CustomerStatus.PENDING).matches(JARNO));
+        assertTrue(new CustomerFilter("", Set.of()).matches(JARNO));
+    }
+
+    @Test
+    void bothPartsMustMatch() {
+        CustomerFilter filter = new CustomerFilter("aaltonen", Set.of(CustomerStatus.CLOSED));
+        assertFalse(filter.matches(ADA), "right name, wrong status");
+        assertTrue(filter.matches(JOSEPHINE));
+    }
+
+    @Test
+    void statusesComeBackInDeclarationOrder() {
+        CustomerFilter filter = CustomerFilter.byStatus(CustomerStatus.CLOSED, CustomerStatus.ACTIVE);
+        assertEquals(List.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED),
+                filter.statusesInDeclarationOrder());
+    }
+
+    @Test
+    void equalFiltersAreEqualWhateverTheyWereBuiltFrom() {
+        assertEquals(new CustomerFilter(" ada  aal ", Set.of(CustomerStatus.CLOSED, CustomerStatus.ACTIVE)),
+                new CustomerFilter("ada aal", Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED)));
+        assertEquals(CustomerFilter.EMPTY, new CustomerFilter(null, null));
+    }
+}
