@@ -0,0 +1,65 @@
+package com.example.customers.ui;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.Set;
+
+import com.example.customers.domain.CustomerFilter;
+import com.example.customers.domain.CustomerStatus;
+
+import com.vaadin.flow.router.QueryParameters;
+import org.junit.jupiter.api.Test;
+
+/** The filter as it travels in a link. */
+class CustomerListViewUrlTest {
+
+    @Test
+    void emptyFilterLeavesNoParametersBehind() {
+        assertEquals("", CustomerListView.toQueryString(CustomerFilter.EMPTY));
+    }
+
+    @Test
+    void bothPartsAreWritten() {
+        CustomerFilter filter = new CustomerFilter("vir", Set.of(CustomerStatus.CLOSED, CustomerStatus.ACTIVE));
+        assertEquals("name=vir&status=ACTIVE,CLOSED", CustomerListView.toQueryString(filter));
+    }
+
+    @Test
+    void onlyTheFilteredPartIsWritten() {
+        assertEquals("name=vir", CustomerListView.toQueryString(CustomerFilter.byName("vir")));
+        assertEquals("status=PENDING",
+                CustomerListView.toQueryString(CustomerFilter.byStatus(CustomerStatus.PENDING)));
+    }
+
+    @Test
+    void spacesAndAccentsSurviveTheTrip() {
+        CustomerFilter filter = CustomerFilter.byName("ada aaltonen");
+        assertEquals("name=ada%20aaltonen", CustomerListView.toQueryString(filter));
+        assertEquals(filter, roundTrip(filter));
+        assertEquals(CustomerFilter.byName("mäkinen"), roundTrip(CustomerFilter.byName("mäkinen")));
+    }
+
+    @Test
+    void parsingAcceptsWhatWritingProduces() {
+        CustomerFilter filter = new CustomerFilter("vir", Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED));
+        assertEquals(filter, roundTrip(filter));
+    }
+
+    @Test
+    void missingParametersMeanNoFilter() {
+        assertTrue(CustomerListView.parseFilter(QueryParameters.empty()).isEmpty());
+        assertTrue(CustomerListView.parseFilter(QueryParameters.fromString("other=1")).isEmpty());
+    }
+
+    @Test
+    void unknownStatusesAreIgnored() {
+        assertEquals(CustomerFilter.byStatus(CustomerStatus.ACTIVE),
+                CustomerListView.parseFilter(QueryParameters.fromString("status=ACTIVE,NOPE")));
+    }
+
+    private static CustomerFilter roundTrip(CustomerFilter filter) {
+        return CustomerListView.parseFilter(
+                QueryParameters.fromString(CustomerListView.toQueryString(filter)));
+    }
+}
